INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Mars', 'Moon', 'trine', 'Góc tam hợp mang lại dòng chảy hài hòa và sự may mắn tự nhiên giữa Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục) và Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng). Hai hành tinh bổ trợ cho nhau một cách hoàn hảo.', 'Trong cuộc sống hàng ngày, sự kết hợp giữa năng lượng hành động, lòng dũng cảm và ham muốn chinh phục và thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng diễn ra vô cùng tự nhiên, không gặp phải sự gượng ép hay trở ngại đáng kể.', 'Tài năng bẩm sinh, sự an ổn trong tâm hồn, sức hút tự nhiên và khả năng gặt hái thành công trôi chảy. (Sao Hỏa - Mặt Trăng)', 'Có nguy cơ sinh ra tâm lý tự mãn hoặc thiếu động lực bứt phá khi đối mặt với những thử thách thực sự lớn. (Sao Hỏa - Mặt Trăng)', '', '', ARRAY['Góc chiếu Tam Hợp', 'Sao Hỏa', 'Mặt Trăng']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Mars', 'Moon', 'square', 'Góc vuông góc tạo ra sự căng thẳng và thử thách nội tâm giữa Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục) và Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng). Đây là động lực áp lực thúc đẩy sự trưởng thành vượt bậc.', 'Trong cuộc sống hàng ngày, bạn thường xuyên cảm thấy sự giằng xé giữa đòi hỏi về năng lượng hành động, lòng dũng cảm và ham muốn chinh phục và nhu cầu về thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng.', 'Ý chí kiên cường, bản lĩnh vượt khó phi thường và khả năng chuyển hóa áp lực xung đột thành sức mạnh bứt phá. (Sao Hỏa - Mặt Trăng)', 'Dễ rơi vào trạng thái căng thẳng thần kinh hoặc bực bội nội tâm khi chưa học được cách dung hòa hai năng lượng. (Sao Hỏa - Mặt Trăng)', '', '', ARRAY['Góc chiếu Vuông Góc', 'Sao Hỏa', 'Mặt Trăng']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Mars', 'Moon', 'opposition', 'Góc xung chiếu tạo sự đối lập và đòi hỏi sự cân bằng giữa Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục) và Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng). Hai mặt của một trục năng lượng cần được dung hòa hài hòa.', 'Trong cuộc sống hàng ngày, bạn hay thấy mình đứng giữa hai cực: một bên là năng lượng hành động, lòng dũng cảm và ham muốn chinh phục và bên kia là thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng, thường phản chiếu qua các mối quan hệ.', 'Tầm nhìn khách quan đa chiều, khả năng thấu hiểu tâm lý đối phương và năng lực đàm phán, hòa giải tuyệt vời khi đã trưởng thành. (Sao Hỏa - Mặt Trăng)', 'Cảm giác dao động mâu thuẫn giữa nhu cầu cá nhân và kỳ vọng từ người khác trước khi đạt được sự cân bằng. (Sao Hỏa - Mặt Trăng)', '', '', ARRAY['Góc chiếu Xung Chiếu', 'Sao Hỏa', 'Mặt Trăng']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Mars', 'Moon', 'semi-sextile', 'Góc bán lục hợp mang đến sự tương tác tinh tế giữa Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục) và Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng). Hai năng lượng kề nhau thúc đẩy sự tinh chỉnh vi mô liên tục.', 'Trong cuộc sống hàng ngày, bạn nhận thấy những góc nhìn khác biệt nhỏ giữa năng lượng hành động, lòng dũng cảm và ham muốn chinh phục và thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng, đòi hỏi sự linh hoạt điều chỉnh trong ứng xử.', 'Khả năng quan sát tinh tế, sự nhạy cảm với các chi tiết nhỏ và năng lực thích ứng linh hoạt. (Sao Hỏa - Mặt Trăng)', 'Cảm giác lấn cấn nhỏ dai dẳng nếu không chú ý lắng nghe và đáp ứng các nhu cầu vi mô của bản thân. (Sao Hỏa - Mặt Trăng)', '', '', ARRAY['Góc chiếu Bán Lục Hợp', 'Sao Hỏa', 'Mặt Trăng']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Mars', 'Moon', 'quincunx', 'Góc bất bất hợp (150°) đòi hỏi sự tái điều chỉnh liên tục giữa Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục) và Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng). Hai nguồn năng lượng không có điểm chung tự nhiên.', 'Trong cuộc sống hàng ngày, bạn cần chủ động sắp xếp để năng lượng hành động, lòng dũng cảm và ham muốn chinh phục không làm gián đoạn hoặc gây mâu thuẫn với thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng.', 'Khả năng giải quyết vấn đề tháo vát, tinh thần linh hoạt và năng lực thích nghi với các tình huống bất ngờ. (Sao Hỏa - Mặt Trăng)', 'Dễ bị mệt mỏi tinh thần hoặc căng thẳng sức khỏe nhẹ do phải liên tục điều chỉnh nhịp sống. (Sao Hỏa - Mặt Trăng)', '', '', ARRAY['Góc chiếu Bất Bất Hợp', 'Sao Hỏa', 'Mặt Trăng']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Jupiter', 'Moon', 'conjunction', 'Góc trùng hợp mang lại sự hợp nhất mãnh liệt giữa Sao Mộc (niềm tin, sự may mắn và khát vọng phát triển tri thức) và Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng). Hai nguồn năng lượng hòa cùng một nhịp, định hình một nét cá tính nổi bật và nhất quán.', 'Trong cuộc sống hàng ngày, bạn thể hiện sự gắn kết tự nhiên giữa niềm tin, sự may mắn và khát vọng phát triển tri thức và thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng. Mọi phản ứng diễn ra trực tiếp, bộc phát theo bản năng thống nhất của cả hai hành tinh.', 'Sự tập trung năng lượng cao, tinh thần nhất quán nội tâm và khả năng bộc lộ cá tính ấn tượng. (Sao Mộc - Mặt Trăng)', 'Đôi khi khó tách bạch các góc nhìn khác nhau. Dễ bị cuốn vào sự chủ quan khi hai nguồn năng lượng quá hòa nhập. (Sao Mộc - Mặt Trăng)', '', '', ARRAY['Góc chiếu Trùng Hợp', 'Sao Mộc', 'Mặt Trăng']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Jupiter', 'Moon', 'sextile', 'Góc lục hợp tạo cơ hội thuận lợi và sự hỗ trợ nhịp nhàng giữa Sao Mộc (niềm tin, sự may mắn và khát vọng phát triển tri thức) và Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng). Năng lượng tuôn chảy nhẹ nhàng, kích thích tiềm năng phát triển.', 'Trong cuộc sống hàng ngày, bạn dễ dàng kết hợp niềm tin, sự may mắn và khát vọng phát triển tri thức với thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng để gặt hái kết quả tích cực và nắm bắt cơ hội một cách hiệu quả.', 'Sự linh hoạt trong tư duy, kỹ năng kết nối tốt và tinh thần chủ động học hỏi, thích ứng nhanh. (Sao Mộc - Mặt Trăng)', 'Nếu không tự giác đặt ra thách thức và hành động, các cơ hội thuận lợi có thể bị trôi qua một cách thụ động. (Sao Mộc - Mặt Trăng)', '', '', ARRAY['Góc chiếu Lục Hợp', 'Sao Mộc', 'Mặt Trăng']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Jupiter', 'Moon', 'trine', 'Góc tam hợp mang lại dòng chảy hài hòa và sự may mắn tự nhiên giữa Sao Mộc (niềm tin, sự may mắn và khát vọng phát triển tri thức) và Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng). Hai hành tinh bổ trợ cho nhau một cách hoàn hảo.', 'Trong cuộc sống hàng ngày, sự kết hợp giữa niềm tin, sự may mắn và khát vọng phát triển tri thức và thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng diễn ra vô cùng tự nhiên, không gặp phải sự gượng ép hay trở ngại đáng kể.', 'Tài năng bẩm sinh, sự an ổn trong tâm hồn, sức hút tự nhiên và khả năng gặt hái thành công trôi chảy. (Sao Mộc - Mặt Trăng)', 'Có nguy cơ sinh ra tâm lý tự mãn hoặc thiếu động lực bứt phá khi đối mặt với những thử thách thực sự lớn. (Sao Mộc - Mặt Trăng)', '', '', ARRAY['Góc chiếu Tam Hợp', 'Sao Mộc', 'Mặt Trăng']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
