INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Jupiter', 'Mercury', 'trine', 'Góc tam hợp mang lại dòng chảy hài hòa và sự may mắn tự nhiên giữa Sao Mộc (niềm tin, sự may mắn và khát vọng phát triển tri thức) và Sao Thủy (tư duy, giao tiếp và khả năng xử lý thông tin). Hai hành tinh bổ trợ cho nhau một cách hoàn hảo.', 'Trong cuộc sống hàng ngày, sự kết hợp giữa niềm tin, sự may mắn và khát vọng phát triển tri thức và tư duy, giao tiếp và khả năng xử lý thông tin diễn ra vô cùng tự nhiên, không gặp phải sự gượng ép hay trở ngại đáng kể.', 'Tài năng bẩm sinh, sự an ổn trong tâm hồn, sức hút tự nhiên và khả năng gặt hái thành công trôi chảy. (Sao Mộc - Sao Thủy)', 'Có nguy cơ sinh ra tâm lý tự mãn hoặc thiếu động lực bứt phá khi đối mặt với những thử thách thực sự lớn. (Sao Mộc - Sao Thủy)', '', '', ARRAY['Góc chiếu Tam Hợp', 'Sao Mộc', 'Sao Thủy']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Jupiter', 'Mercury', 'square', 'Góc vuông góc tạo ra sự căng thẳng và thử thách nội tâm giữa Sao Mộc (niềm tin, sự may mắn và khát vọng phát triển tri thức) và Sao Thủy (tư duy, giao tiếp và khả năng xử lý thông tin). Đây là động lực áp lực thúc đẩy sự trưởng thành vượt bậc.', 'Trong cuộc sống hàng ngày, bạn thường xuyên cảm thấy sự giằng xé giữa đòi hỏi về niềm tin, sự may mắn và khát vọng phát triển tri thức và nhu cầu về tư duy, giao tiếp và khả năng xử lý thông tin.', 'Ý chí kiên cường, bản lĩnh vượt khó phi thường và khả năng chuyển hóa áp lực xung đột thành sức mạnh bứt phá. (Sao Mộc - Sao Thủy)', 'Dễ rơi vào trạng thái căng thẳng thần kinh hoặc bực bội nội tâm khi chưa học được cách dung hòa hai năng lượng. (Sao Mộc - Sao Thủy)', '', '', ARRAY['Góc chiếu Vuông Góc', 'Sao Mộc', 'Sao Thủy']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Jupiter', 'Mercury', 'opposition', 'Góc xung chiếu tạo sự đối lập và đòi hỏi sự cân bằng giữa Sao Mộc (niềm tin, sự may mắn và khát vọng phát triển tri thức) và Sao Thủy (tư duy, giao tiếp và khả năng xử lý thông tin). Hai mặt của một trục năng lượng cần được dung hòa hài hòa.', 'Trong cuộc sống hàng ngày, bạn hay thấy mình đứng giữa hai cực: một bên là niềm tin, sự may mắn và khát vọng phát triển tri thức và bên kia là tư duy, giao tiếp và khả năng xử lý thông tin, thường phản chiếu qua các mối quan hệ.', 'Tầm nhìn khách quan đa chiều, khả năng thấu hiểu tâm lý đối phương và năng lực đàm phán, hòa giải tuyệt vời khi đã trưởng thành. (Sao Mộc - Sao Thủy)', 'Cảm giác dao động mâu thuẫn giữa nhu cầu cá nhân và kỳ vọng từ người khác trước khi đạt được sự cân bằng. (Sao Mộc - Sao Thủy)', '', '', ARRAY['Góc chiếu Xung Chiếu', 'Sao Mộc', 'Sao Thủy']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Jupiter', 'Mercury', 'semi-sextile', 'Góc bán lục hợp mang đến sự tương tác tinh tế giữa Sao Mộc (niềm tin, sự may mắn và khát vọng phát triển tri thức) và Sao Thủy (tư duy, giao tiếp và khả năng xử lý thông tin). Hai năng lượng kề nhau thúc đẩy sự tinh chỉnh vi mô liên tục.', 'Trong cuộc sống hàng ngày, bạn nhận thấy những góc nhìn khác biệt nhỏ giữa niềm tin, sự may mắn và khát vọng phát triển tri thức và tư duy, giao tiếp và khả năng xử lý thông tin, đòi hỏi sự linh hoạt điều chỉnh trong ứng xử.', 'Khả năng quan sát tinh tế, sự nhạy cảm với các chi tiết nhỏ và năng lực thích ứng linh hoạt. (Sao Mộc - Sao Thủy)', 'Cảm giác lấn cấn nhỏ dai dẳng nếu không chú ý lắng nghe và đáp ứng các nhu cầu vi mô của bản thân. (Sao Mộc - Sao Thủy)', '', '', ARRAY['Góc chiếu Bán Lục Hợp', 'Sao Mộc', 'Sao Thủy']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Jupiter', 'Mercury', 'quincunx', 'Góc bất bất hợp (150°) đòi hỏi sự tái điều chỉnh liên tục giữa Sao Mộc (niềm tin, sự may mắn và khát vọng phát triển tri thức) và Sao Thủy (tư duy, giao tiếp và khả năng xử lý thông tin). Hai nguồn năng lượng không có điểm chung tự nhiên.', 'Trong cuộc sống hàng ngày, bạn cần chủ động sắp xếp để niềm tin, sự may mắn và khát vọng phát triển tri thức không làm gián đoạn hoặc gây mâu thuẫn với tư duy, giao tiếp và khả năng xử lý thông tin.', 'Khả năng giải quyết vấn đề tháo vát, tinh thần linh hoạt và năng lực thích nghi với các tình huống bất ngờ. (Sao Mộc - Sao Thủy)', 'Dễ bị mệt mỏi tinh thần hoặc căng thẳng sức khỏe nhẹ do phải liên tục điều chỉnh nhịp sống. (Sao Mộc - Sao Thủy)', '', '', ARRAY['Góc chiếu Bất Bất Hợp', 'Sao Mộc', 'Sao Thủy']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Mercury', 'Saturn', 'conjunction', 'Góc trùng hợp mang lại sự hợp nhất mãnh liệt giữa Sao Thủy (tư duy, giao tiếp và khả năng xử lý thông tin) và Sao Thổ (tính kỷ luật, tinh thần trách nhiệm và các giới hạn). Hai nguồn năng lượng hòa cùng một nhịp, định hình một nét cá tính nổi bật và nhất quán.', 'Trong cuộc sống hàng ngày, bạn thể hiện sự gắn kết tự nhiên giữa tư duy, giao tiếp và khả năng xử lý thông tin và tính kỷ luật, tinh thần trách nhiệm và các giới hạn. Mọi phản ứng diễn ra trực tiếp, bộc phát theo bản năng thống nhất của cả hai hành tinh.', 'Sự tập trung năng lượng cao, tinh thần nhất quán nội tâm và khả năng bộc lộ cá tính ấn tượng. (Sao Thủy - Sao Thổ)', 'Đôi khi khó tách bạch các góc nhìn khác nhau. Dễ bị cuốn vào sự chủ quan khi hai nguồn năng lượng quá hòa nhập. (Sao Thủy - Sao Thổ)', '', '', ARRAY['Góc chiếu Trùng Hợp', 'Sao Thủy', 'Sao Thổ']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Mercury', 'Saturn', 'sextile', 'Góc lục hợp tạo cơ hội thuận lợi và sự hỗ trợ nhịp nhàng giữa Sao Thủy (tư duy, giao tiếp và khả năng xử lý thông tin) và Sao Thổ (tính kỷ luật, tinh thần trách nhiệm và các giới hạn). Năng lượng tuôn chảy nhẹ nhàng, kích thích tiềm năng phát triển.', 'Trong cuộc sống hàng ngày, bạn dễ dàng kết hợp tư duy, giao tiếp và khả năng xử lý thông tin với tính kỷ luật, tinh thần trách nhiệm và các giới hạn để gặt hái kết quả tích cực và nắm bắt cơ hội một cách hiệu quả.', 'Sự linh hoạt trong tư duy, kỹ năng kết nối tốt và tinh thần chủ động học hỏi, thích ứng nhanh. (Sao Thủy - Sao Thổ)', 'Nếu không tự giác đặt ra thách thức và hành động, các cơ hội thuận lợi có thể bị trôi qua một cách thụ động. (Sao Thủy - Sao Thổ)', '', '', ARRAY['Góc chiếu Lục Hợp', 'Sao Thủy', 'Sao Thổ']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Mercury', 'Saturn', 'trine', 'Góc tam hợp mang lại dòng chảy hài hòa và sự may mắn tự nhiên giữa Sao Thủy (tư duy, giao tiếp và khả năng xử lý thông tin) và Sao Thổ (tính kỷ luật, tinh thần trách nhiệm và các giới hạn). Hai hành tinh bổ trợ cho nhau một cách hoàn hảo.', 'Trong cuộc sống hàng ngày, sự kết hợp giữa tư duy, giao tiếp và khả năng xử lý thông tin và tính kỷ luật, tinh thần trách nhiệm và các giới hạn diễn ra vô cùng tự nhiên, không gặp phải sự gượng ép hay trở ngại đáng kể.', 'Tài năng bẩm sinh, sự an ổn trong tâm hồn, sức hút tự nhiên và khả năng gặt hái thành công trôi chảy. (Sao Thủy - Sao Thổ)', 'Có nguy cơ sinh ra tâm lý tự mãn hoặc thiếu động lực bứt phá khi đối mặt với những thử thách thực sự lớn. (Sao Thủy - Sao Thổ)', '', '', ARRAY['Góc chiếu Tam Hợp', 'Sao Thủy', 'Sao Thổ']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
